struct timeval tv;
struct timezone tz;
int status;

// Retrieve time (seconds and microseconds)
status = gettimeofday(&tv, &tz);

// Often used with NULL for timezone parameter
status = gettimeofday(&tv, NULL);

// Check status (0 on success)
if (status == 0) {
    long seconds = (long)tv.tv_sec;
    long microseconds = (long)tv.tv_usec;
}

